import fs from 'node:fs';import path from 'node:path';import {createHash} from 'node:crypto';import {journalLines} from '../live-paper/journal-lines.mjs';import {sealedNativePrefix} from '../live-paper/native-dip-host-v1.mjs';import {engineBookPointsV1} from '../paper/maker-engine-book-point-v1.mjs';import {createCausalBookStudyV1} from '../research/causal-book-strategy-study-v1.mjs';
const rt=path.join(process.env.LOCALAPPDATA,'SigTradingCup/paper-runtime'),session=JSON.parse(fs.readFileSync(path.join(rt,'realtime-session.json')));if(!/^realtime-[A-Za-z0-9.-]+\.jsonl$/.test(session.file))throw Error('STUDY_SOURCE_PATH');const file=path.join(rt,session.file),seal=sealedNativePrefix(file),through=new Date().toISOString(),splitAt=new Date(Date.parse(session.startedAt)+.7*(Date.parse(through)-Date.parse(session.startedAt))).toISOString(),scope={tournamentId:session.scope.tournamentId,exchanges:session.scope.markets},study=createCausalBookStudyV1(),prefix=createHash('sha256'),sampled=new Map(),revisions=new Map();let index=0,accepted=0,rejected=0;const started=performance.now();for(const line of journalLines(file,{endByte:seal.bytes})){prefix.update(line+'\n');const r=JSON.parse(line);if(r.format!=='sig-feed-capture'||r.captureIndex!==index++)throw Error('STUDY_CAPTURE_CHAIN');if(r.kind!=='event'||r.event!=='market_batch')continue;const key=r.topic+':'+r.epoch,rev=r.payload?.delivery?.revision;if(!Number.isSafeInteger(rev)||rev<=(revisions.get(key)??-1))continue;revisions.set(key,rev);const at=Date.parse(r.observedAt);if(at-(sampled.get(key)??-Infinity)<1000)continue;sampled.set(key,at);const result=engineBookPointsV1(r,scope,r.observedAt);rejected+=result.rejected.length;for(const b of result.books){study.observe(b,r.observedAt);accepted++;}}const current=fs.statSync(file);if(current.dev!==seal.dev||current.ino!==seal.ino||current.size<seal.bytes)throw Error('STUDY_SOURCE_REPLACED');const report={at:new Date().toISOString(),source:{file:session.file,bytes:seal.bytes,sha256:prefix.digest('hex'),captureRecords:index,from:session.startedAt,through},timingMs:performance.now()-started,acceptedPoints:accepted,rejectedPoints:rejected,...study.report({splitAt}),limitations:['Per-unit probes, not a funded portfolio or actual executions.','Book points sampled at most once per topic per second.','Source prices/latency/spread are causal; exact taker acceptance and queue are unknown.','Eight prespecified variants on one chronological development/heldout split; no selection adjusted confidence claim.','No fees; one-tick-each-way stress shown separately.'],networkRequests:0,contestOrders:0};fs.writeFileSync('data/causal-book-study-20261013.json',JSON.stringify(report));console.log(JSON.stringify({source:report.source,timingMs:report.timingMs,points:accepted,variants:report.variants.map(({outcomes,...v})=>v)}));
